probes={}
for args in ([['docker','--version'],['docker','info','--format','{{.OSType}}'],['docker','version','--format','{{.Server.Os}}/{{.Server.Arch}}']]):
    key=' '.join(args)
    try:
        r=subprocess.run(args,capture_output=True,text=True,timeout=15)
        probes[key]={'returncode':r.returncode,'stdout':r.stdout.strip(),'stderr':r.stderr.strip()[:500]}
    except Exception as e:
        probes[key]={'exception':type(e).__name__+': '+str(e)}
print(json.dumps(probes,indent=1))
print('disk_usage=',shutil.disk_usage('/'))
print('disk_usage_tmp=',shutil.disk_usage('/tmp'))"]

